  'Municipal Demarcation Board, MDB Wards 2026, WardID 79800109 (effective 2026-11-04)', true
FROM public.wards WHERE ward_number = 109;

-- Suburb centres for Buccleuch and Woodmead fall outside the 2026 boundary, so only parts are in Ward 109.
UPDATE public.suburbs SET coverage = 'partial'
WHERE name IN ('Buccleuch', 'Woodmead')
  AND ward_id = (SELECT id FROM public.wards WHERE ward_number = 109);

-- The official boundary is public geographic information (no personal data): let the public map read it.
GRANT SELECT ON public.ward_boundaries TO anon;
CREATE POLICY "Active boundaries are public" ON public.ward_boundaries FOR SELECT
  USING (is_active);

